    junc: { m: ['cruce'], t: 'Cruce', d: 'Un punto unido a otros cuatro (d6, b4, f4, d2): pasan dos líneas de molino y es el más móvil.' },
    corner: { m: ['esquina'], t: 'Esquina', d: 'Un punto de esquina (a7, g7, a1, g1…): solo dos vecinos, difícil de mover.' },
    thr: { m: ['amenaza'], t: 'Amenaza', d: 'Una línea con dos fichas propias y el tercer punto libre: se puede formar molino en la próxima jugada.' },
    block: { m: ['bloquea', 'Bloquea'], t: 'Bloquear', d: 'Poner una ficha en el punto libre de una amenaza rival: la defensa básica contra un molino.' },
    fly: { m: ['volar'], t: 'Vuelo', d: 'Quien tiene tres fichas puede mover una a cualquier punto libre, no solo a uno vecino.' },
