    corner: { m: ['canto'], t: 'Canto', d: 'Um ponto de canto (a7, g7, a1, g1…): só dois vizinhos, difícil de mover.' },
    thr: { m: ['ameaça'], t: 'Ameaça', d: 'Uma linha com duas peças suas e o terceiro ponto livre: dá para formar moinho no próximo lance.' },
    block: { m: ['bloqueie', 'Bloqueie'], t: 'Bloquear', d: 'Colocar uma peça no ponto livre de uma ameaça adversária: a defesa básica contra um moinho.' },
    fly: { m: ['voar'], t: 'Voo', d: 'Quem tem três peças pode mover uma para qualquer ponto livre, não só para um vizinho.' },
